(102189, 4281, 2983, '<td valign="top">This is quite hillarious.  Points for creativity, and a good shot anyways.</td>', 'This is quite hillarious.  Points for creativity, and a good shot anyways.', '2002-08-19 00:42:00.000000', NULL, 1),
(102190, 4282, 3127, '<td valign="top">Grainy at higher resolution. Good composition, but color of new baby may have added to the photo composition</td>', 'Grainy at higher resolution. Good composition, but color of new baby may have added to the photo composition', '2002-08-12 10:09:00.000000', NULL, 1),
(102191, 4282, 1779, '<td valign="top">I don''t care about the clichè. But it''s way to grainyand OOF. I know it''s the camera though...</td>', 'I don''t care about the clichè. But it''s way to grainyand OOF. I know it''s the camera though...', '2002-08-12 12:50:00.000000', NULL, 1),
