(102525, 4307, 3102, '<td valign="top">It''s out of focus and not too visually interesting... sorry...</td>', 'It''s out of focus and not too visually interesting... sorry...', '2002-08-12 20:08:00.000000', NULL, 1),
(102526, 4307, 2353, '<td valign="top">a little fuzzy...it looks like it was taken from the other side of a car window...maybe if you had gotten in front of it and took a shot from below the sign looking up it would have been more dynamic?  The power lines also distract me...</td>', 'a little fuzzy...it looks like it was taken from the other side of a car window...maybe if you had gotten in front of it and took a shot from below the sign looking up it would have been more dynamic?  The power lines also distract me...', '2002-08-12 21:04:00.000000', NULL, 1),
(102527, 4307, 1202, '<td valign="top">Composition6<br/>Technical Aspects6<br/>Appeal6<br/>Creativity7<br/>Rating6Autool<br/></td>', 'Composition6Technical Aspects6Appeal6Creativity7Rating6Autool', '2002-08-12 21:59:00.000000', NULL, 1),
