(102670, 4313, 3198, '<td valign="top">beatiful shot. nice close up and depth</td>', 'beatiful shot. nice close up and depth', '2002-08-12 10:13:00.000000', NULL, 1),
(102671, 4313, 3002, '<td valign="top">Well, this shot is certainly predictable, but a superb closeup that SCREAMS new, not just because it''s a baby.  Very good work.  (And what a precious little miracle, huh?)</td>', 'Well, this shot is certainly predictable, but a superb closeup that SCREAMS new, not just because it''s a baby.  Very good work.  (And what a precious little miracle, huh?)', '2002-08-12 12:44:00.000000', NULL, 1),
