(102959, 4333, 3044, '<td valign="top">nice.</td>', 'nice.', '2002-08-12 18:06:00.000000', NULL, 1),
(102960, 4333, 2754, '<td valign="top">I like the picture, but I think I would have set the hands at exactly 12:00, and gotten the ticks of the second hand passing the 12.  JMHO</td>', 'I like the picture, but I think I would have set the hands at exactly 12:00, and gotten the ticks of the second hand passing the 12.  JMHO', '2002-08-12 18:39:00.000000', NULL, 1),
