(103577, 4376, 1154, '<td valign="top">Magnificent Sky!</td>', 'Magnificent Sky!', '2002-08-14 10:29:00.000000', NULL, 1),
(103578, 4376, 2350, '<td valign="top">Why no foilage on trees  and is it really a new day??? Questionable when taken.</td>', 'Why no foilage on trees  and is it really a new day??? Questionable when taken.', '2002-08-14 12:39:00.000000', NULL, 1),
(103579, 4376, 1875, '<td valign="top">not original, but gorgeous pic</td>', 'not original, but gorgeous pic', '2002-08-14 18:43:00.000000', NULL, 1),
(103580, 4376, 2716, '<td valign="top">How does that go.  Red sky at night, fisheman''s delight.  Red Sky in the morning, take warning.  Boys I messed that up.  Looked like a pretty nasty day coming up.  Very nice colours (6).</td>', 'How does that go.  Red sky at night, fisheman''s delight.  Red Sky in the morning, take warning.  Boys I messed that up.  Looked like a pretty nasty day coming up.  Very nice colours (6).', '2002-08-14 22:15:00.000000', NULL, 1),
