(103752, 4394, 1792, '<td valign="top">Interesting, effective composition.  No one should question that it''s a new building.</td>', 'Interesting, effective composition.  No one should question that it''s a new building.', '2002-08-14 00:59:00.000000', NULL, 1),
(103753, 4394, 2798, '<td valign="top">More "new sky" than "new building" :-) The arrangement jars a little since there''s no natural place for your eye to sit. Interesting shapes though.</td>', 'More "new sky" than "new building" :-) The arrangement jars a little since there''s no natural place for your eye to sit. Interesting shapes though.', '2002-08-15 07:41:00.000000', NULL, 1),
(103754, 4394, 3173, '<td valign="top">Ok, I am certainly no expert, but I just love this photo...The building frames the sky beautifully! Very nice pic :)</td>', 'Ok, I am certainly no expert, but I just love this photo...The building frames the sky beautifully! Very nice pic :)', '2002-08-15 13:31:00.000000', NULL, 1),
