(104788, 4448, 656, '<td valign="top">nice spiral/ twirl effect going on - ironic with the new challenge :)</td>', 'nice spiral/ twirl effect going on - ironic with the new challenge :)', '2002-08-12 23:09:00.000000', NULL, 1),
(104789, 4448, 2591, '<td valign="top">Perhaps you have a sixth sense as your shot is ideally suited to this weeks challenge.</td>', 'Perhaps you have a sixth sense as your shot is ideally suited to this weeks challenge.', '2002-08-12 23:23:00.000000', NULL, 1),
(104790, 4448, 1095, '<td valign="top">Very graphic. Love the "from the top" angle!</td>', 'Very graphic. Love the "from the top" angle!', '2002-08-13 01:08:00.000000', NULL, 1),
(104791, 4448, 3189, '<td valign="top">Would have been good for this week ...</td>', 'Would have been good for this week ...', '2002-08-13 09:10:00.000000', NULL, 1),
